import java.util.*;
import java.io.*;

public class p1096g_v2 {
    private static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long[] base = new long[10];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            base[Integer.parseInt(st.nextToken())] = 1;
        }
        long[] result = power(base, n / 2);
        long sum = 0;
        for (long x : result) {
            sum = (sum + x * x % MOD) % MOD;
        }
        System.out.println(sum);
    }

    private static long[] power(long[] base, long exponent) {
        if (exponent == 1) return base;
        if ((exponent & 1) == 1) {
            return FFT.multiplyPrecise(base, power(base, exponent - 1));
        }
        long[] half = power(base, exponent >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        private static final int MAX_K = 21;
        private static final int MAX_N = 1 << MAX_K;
        private static final double[] wR = new double[MAX_N];
        private static final double[] wI = new double[MAX_N];
        private static final double[] aR = new double[MAX_N];
        private static final double[] aI = new double[MAX_N];
        private static int n, k, lastK = -1;
        private static final int[] rev = new int[MAX_N];

        private static void transform(boolean inverse) {
            if (lastK != k) {
                lastK = k;
                rev[0] = 0;
                for (int i = 1, g = 0; i < n; i++) {
                    if ((i & (i - 1)) == 0) g++;
                    rev[i] = rev[i ^ (1 << g)] ^ (1 << (k - 1 - g));
                }
                wR[1] = 1;
                wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / n * (1 << (k - 1 - t));
                    double cosVal = Math.cos(angle);
                    double sinVal = Math.sin(angle);
                    int p2 = 1 << t;
                    int p3 = p2 << 1;
                    for (int j = p2, idx = p3; j < p3; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * cosVal - wI[j] * sinVal;
                        wI[idx + 1] = wR[j] * sinVal + wI[j] * cosVal;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                int r = rev[i];
                if (i < r) {
                    double tmp = aR[i];
                    aR[i] = aR[r];
                    aR[r] = tmp;
                    tmp = aI[i];
                    aI[i] = aI[r];
                    aI[r] = tmp;
                }
            }
            if (inverse) {
                for (int i = 0; i < n; i++) aI[i] = -aI[i];
            }
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len) {
                    int wIdx = len;
                    for (int j = i + len, it = 0; it < len; it++, i++, j++) {
                        double tr = aR[j] * wR[wIdx] - aI[j] * wI[wIdx];
                        double ti = aR[j] * wI[wIdx] + aI[j] * wR[wIdx];
                        wIdx++;
                        aR[j] = aR[i] - tr;
                        aI[j] = aI[i] - ti;
                        aR[i] += tr;
                        aI[i] += ti;
                    }
                }
            }
        }

        private static long[] multiply(long[] x, long[] y) {
            int lenX = x.length, lenY = y.length;
            for (k = 0, n = 1; n < lenX + lenY - 1; n <<= 1, k++) {}
            for (int i = 0; i < n; i++) {
                aR[i] = (i < lenX) ? x[i] : 0;
                aI[i] = (i < lenY) ? y[i] : 0;
            }
            transform(false);
            aR[n] = aR[0];
            aI[n] = aI[0];
            double scale = -1.0 / n / 4.0;
            for (int i = 0; i <= n - i; i++) {
                double r1 = aR[i] * aR[i] - aI[i] * aI[i];
                double i1 = 2 * aR[i] * aI[i];
                double r2 = aR[n - i] * aR[n - i] - aI[n - i] * aI[n - i];
                double i2 = -2 * aR[n - i] * aI[n - i];
                double nr = -i1 + i2;
                double ni = r1 - r2;
                aR[i] = nr * scale;
                aI[i] = ni * scale;
                aR[n - i] = aR[i];
                aI[n - i] = -aI[i];
            }
            transform(true);
            long[] res = new long[lenX + lenY - 1];
            for (int i = 0; i < res.length; i++) {
                res[i] = Math.round(aR[i]) % MOD;
            }
            return res;
        }

        static long[] multiplyPrecise(long[] x, long[] y) {
            long sqrtMod = (long) Math.sqrt(MOD);
            long[] xl = new long[x.length], xh = new long[x.length];
            long[] yl = new long[y.length], yh = new long[y.length];
            for (int i = 0; i < x.length; i++) {
                xl[i] = x[i] % sqrtMod;
                xh[i] = x[i] / sqrtMod;
            }
            for (int i = 0; i < y.length; i++) {
                yl[i] = y[i] % sqrtMod;
                yh[i] = y[i] / sqrtMod;
            }
            long[] r11 = multiply(xl, yl);
            long[] r12 = multiply(xl, yh);
            long[] r21 = multiply(xh, yl);
            long[] r22 = multiply(xh, yh);
            long[] res = new long[r11.length];
            for (int i = 0; i < res.length; i++) {
                long term1 = (sqrtMod * sqrtMod % MOD) * r22[i] % MOD;
                long term2 = sqrtMod * ((r12[i] + r21[i]) % MOD) % MOD;
                res[i] = (term1 + term2 + r11[i]) % MOD;
            }
            return res;
        }
    }
}
